const fs = await import('node:fs');
const inputPath = process.env.INPUT_PATH;
if (!inputPath) throw new Error('Missing INPUT_PATH environment variable');
globalThis.yamlContent = fs.readFileSync(inputPath, 'utf8');

const yamlMod = await import('js-yaml');
const { load } = yamlMod;
globalThis.parsedObject = load(globalThis.yamlContent);
